class MessageSanityCheckError(Exception):
    pass


class ByteStreamLengthError(Exception):
    pass


class MessageStatusError(Exception):
    pass


class ConnectionError(Exception):
    pass


class ConnectionFailed(ConnectionError):
    pass


class ConnectionClosed(ConnectionError):
    pass


class ConnectionTimedOut(ConnectionError):
    pass


class UnknownServerError(ConnectionError):
    pass


class InvalidHost(ConnectionError):
    pass
